#!/usr/bin/env python3
"""Write scope, exact intervals and per-source coverage beside the figure."""
import csv,json
from collections import Counter
from analyze import BASE,OUT,config,NAMES

def main():
    s=json.loads((OUT/'summary.json').read_text());c=s['config'];prov=json.loads((OUT/'provenance.json').read_text())
    control=json.loads((OUT/'control_audit.json').read_text())
    coverage=list(csv.DictReader((OUT/'round_coverage.csv').open()));cells=list(csv.DictReader((OUT/'heatmap_cells.csv').open()))
    lines=['# Question-controlled semantic distances and trajectories','',
      '[Executed notebook](semantic_trajectory_analysis.ipynb) · [Figure PDF](figures/semantic/semantic.pdf) · [Editable SVG](figures/semantic/semantic.svg)','',
      '## Scope and interpretation','',
      'Settings: '+', '.join(c['labels'][a] for a in c['arms'])+'. Original Astra-low completed traces only; no repairs, cancelled initial-run records, Sol episodes, behavioral categories, LLM judges or outcome plots. The selected evaluation manifest contains 40 questions from each of five source benchmarks (200 total); matched coverage after completeness/round requirements appears below.','',
      '**Raw-distance figure:** The user selected trial 1 only for all five settings. Consequently every off-diagonal cell uses raw cross-persona cosine distance; no cell subtracts repeat variation. This figure cannot establish excess separation over ordinary rollout randomness. The code supports the requested adjusted estimator but refuses it when configured repeats are insufficient.' if c['mode']=='raw' else '**Adjusted-distance figure:** all settings have repeated rollouts. Cells subtract the mean of the two within-persona distances from cross-persona distance. Negative estimates are retained, without interpreting them as negative diversity.','',
      'The diagonal is masked. No significance stars are shown. The two roles share color limits. Manually selected UMAP examples illustrate observed conversations and are not independent statistical evidence. Distance can reflect linguistic style and is not task or reasoning quality. Persona off is explicitly the no-persona control.','',
      '## Shared representation and rounds','',
      f"Frozen model: `{c['model_id']}` at revision `{c['model_revision']}`. Local inference, last-token pooling, 1,024 dimensions, L2 normalization; cosine distance before projection. No API calls, summaries, translation or embedding instructions. Full messages are embedded without truncation; inputs over the model context cause an explicit failure.",'',
      c['preprocessing'],'',c['round_rule'],'',c['availability_rule'],'',
      'Generated initial review requests are included because they are simulator outputs. The fixed SciConv input is excluded because it is benchmark input; its first actor question occurs before the first simulator output and is excluded from the simulator-then-actor pairing. A terminal simulator closing message may have no subsequent actor contribution. Different role coverage is retained explicitly; no response is fabricated.','',
      '## Weighting and uncertainty','',c['weighting'],'',
      f"All configured independent rollout IDs are used: {json.dumps(c['rollouts'])}. At each eligible question/round/role, cross-persona distances average all R_i × R_j pairs. Adjusted mode additionally averages distinct within-persona pairs. Round estimates average within question, then questions average within super-family and each of the four families receives 25% weight. Benchmark weights within a family follow retained question counts. Whole questions are resampled within source × super-family {c['bootstrap_resamples']:,} times (seed {c['seed']}), keeping all their conditions, rounds and rollouts together. Percentile 95% intervals are pointwise, conditional on observed rollouts. No independent resampling of pairwise distances and no multiplicity claim. Questions from a shared source study may be correlated; this figure implements the requested question bootstrap, rather than the study bootstrap used in previous reports.",'',
      'Later rounds condition on every included trajectory continuing to that round. A question missing any required condition/rollout has no eligible rounds for that role. Counts below and the round-coverage CSV expose these restrictions.','',
      '| Role | Source | Matched questions | Eligible question-rounds |','|---|---|---:|---:|']
    for role in c['roles']:
        for src in ['asibench','bixbench','discoverybench','expbench','sciconvbench']:
            rs=[r for r in coverage if r['role']==role and r['source']==src and int(r['eligible_round_count'])]
            lines.append(f"| {role} | {NAMES[src]} | {len(rs)} | {sum(int(r['eligible_round_count']) for r in rs)} |")
    lines+=['','The matched panel contains 41 life-science, 42 physical/engineering, 41 math/CS and 24 social/humanities questions. Each family receives 25% aggregate weight. Singleton benchmark-by-family strata have no estimable within-stratum variation in this bootstrap. Balancing controls field composition, not unobserved rollout randomness. [Question-weighted sensitivity](data/semantic/question_weighted_heatmap_cells.csv) preserves the original weighting and source-stratified CIs.','', '## A — exact family-balanced heatmap estimates','', '| Role | Persona pair | Distance [95% CI] | Questions |','|---|---|---|---:|']
    for r in cells:lines.append(f"| {r['role']} | {c['labels'][r['persona_i']]} / {c['labels'][r['persona_j']]} | {float(r['estimate']):.4f} [{float(r['ci_low']):.4f}, {float(r['ci_high']):.4f}] | {r['questions']} |")
    lines+=['','## B — case selection and projection','',c['case_rule'],'',c['projection'],'',
      '| Source | Question | Selection |','|---|---|---|']
    for case in s['cases']:lines.append(f"| {NAMES[case['source']]} | `{case['task_id']}` | Manual exploratory illustration |")
    lines+=['',f"Every displayed path uses rollout {c['display_rollout']}. Simulator and actor rows show both sides of those same interactions. Nodes are actual observed messages; round indices remain in source data and are omitted from the plotted points; diamonds mark the final observed node. Gentle quadratic curves connect observed rounds for visual clarity; intermediate positions do not represent observed states. Control points use a perpendicular offset of 0.14 times the chord in axis-normalized coordinates; observed node coordinates are unchanged. Directional arrows and point-index labels are omitted; final nodes remain marked by diamonds. Local UMAP axes have no explained-variance percentages; coordinates cannot be compared across subplots and projected distances are not quantitative effect sizes. The five colors consistently identify conditions. There are no forced common origins or interpolated messages. Curvature is a display choice, not an estimated continuous semantic process.",'',
      '## Reproducibility','',
      '- `code/semantic/config.json`: frozen settings, repeat IDs, availability, weighting and case-selection rules.','- `code/semantic/analyze.py extract`: original trace extraction; private current-message text stays in ignored `runs/semantic-analysis/`.','- `code/semantic/embed.py --device cuda`: offline local embedding; cached vectors keyed by model revision and exact message hash.','- `code/semantic/analyze.py analyze`: pairwise estimates, question bootstrap and the frozen user-selected UMAP coordinates.','- `code/semantic/build_notebook.py`: execute the table-and-figure notebook.','',
      f"Analyzed {s['analysis_coverage']['message_count']:,} trial-1 messages from {s['analysis_coverage']['complete_episodes']:,} complete episodes out of {s['analysis_coverage']['episode_slots']:,} trial-1 slots. Exclusions: `{json.dumps(s['analysis_coverage']['exclusions'])}`. The reusable embedding archive also contains later trials, which are filtered out before this analysis and every projection fit.",'',
      f"The recorded-question/model/decoding/protocol audit checked {control['episodes_checked']} complete trial-1 episodes, with {len(control['conflicts'])} mismatched questions and {control['missing_record_count']} missing records. Initial environment files and unrecorded provider defaults were not reconstructed; see [control audit](data/semantic/control_audit.json).",'', '[Heatmap source data](data/semantic/heatmap_cells.csv) · [Question estimates](data/semantic/question_distances.csv) · [Round coverage](data/semantic/round_coverage.csv) · [Message/event index](data/semantic/selected_message_index.csv) · [Embedding and analysis provenance](data/semantic/summary.json)','']
    (BASE/'SEMANTIC_REPORT.md').write_text('\n'.join(lines))

if __name__=='__main__':main()
